def count_house_pair_distances_small(n,x,y):
    answer=[0]*n
    for left in range(1,n+1):
        for right in range(left+1,n+1):
            distance=min(right-left,abs(left-x)+1+abs(right-y),abs(left-y)+1+abs(right-x))
            answer[distance-1]+=2
    return answer

